-    // Apply QK scale correction: score_fp32 = dot(Q_fp8, K_fp8) * q_dyn * k
-    scale *= q_dynamic_scale * k_scale;
-
-    if (q_head_num > AMX_TILE_ROW_NUM) {
-      if (q_head_num != current_q_head_num_) {
