-      const at::BFloat16* __restrict__ A,
-      const at::BFloat16* __restrict__ B,
-      float* __restrict__ C,
-      const index_t* __restrict__ indices,
-      float scale,
-      int64_t lda,
-      int64_t ldb,
-      int64_t ldc,
-      int64_t K,
-      int64_t max_tokens) {
