-      constexpr int row = i / COLS;
-      constexpr int col = i % COLS;
-
-      if constexpr (col == 0) {
-        va = (__m512bh)(_mm512_maskz_loadu_epi16(mask, A + row * lda + k));
-      }
-      if constexpr (row == 0) {
