-    int64_t k = 0;
-    for (; k <= K - 32; k += 32) {
-      Unroll<ROWS * COLS>{}(compute, k);
-    }
-    int64_t count = K - k;
-    if (count > 0) {
-      __mmask32 mask = (1ULL << count) - 1;
-      Unroll<ROWS * COLS>{}(compute2, k, mask);
-    }
