-template <bool convert_v, typename scalar_t, typename index_t, typename load_vec_t>
-inline __attribute__((always_inline)) void sparse_pack_vnni_Nx32(
-    scalar_t* __restrict__ dst0,
-    scalar_t* __restrict__ dst1,
