-          dst1 + ((nb * 16) >> 1) * ld_dst1 * 2 + kb * 32 * 2,
-          ind + nb * 16,
-          valid_mask + nb * 16,
-          nb_size,
-          kb * 32,
-          ld_dst0,
-          ld_dst1,
-          load_vec);
