-  _mm_storeu_si128(reinterpret_cast<__m128i*>(dst + 16), fp8_1);
-  _mm_storeu_si128(reinterpret_cast<__m128i*>(dst + 32), fp8_2);
-  _mm_storeu_si128(reinterpret_cast<__m128i*>(dst + 48), fp8_3);
