-#define LAUNCH_HASH_TOPK_KERNEL(NE, NTOPK)    \
-  hash_topk_kernel_impl<scalar_t, NE, NTOPK>( \
-      topk_weights.data_ptr<float>(),         \
-      topk_ids.data_ptr<int32_t>(),           \
