-struct TopKTransformMinHeapCmp {
-  bool operator()(const TopKTransformElem& lhs, const TopKTransformElem& rhs) const {
-    if (lhs.score == rhs.score) {
-      return lhs.index > rhs.index;
-    }
-    return lhs.score > rhs.score;
-  }
