-namespace {
-
-constexpr int kWarpSize = 32;
-// Sentinel in the shared top-k scratch: entry already resolved (hit /
-// newest / invalid), no miss handling needed.
-constexpr int32_t kTokenDone = -1;
-constexpr int32_t kHashEmpty = -1;
