-    let mut indices = (block_start..block_end)
-        .filter(|index| matches!(messages[*index], ChatMessage::ToolResponse { .. }))
-        .collect::<Vec<_>>();
-    if indices.len() <= 1 || tool_call_order.is_empty() {
